// Presence gate: the same printed SKU is counted again only after leaving the frame.
export function createPresenceGate(rearmMs=900){const lastSeen=new Map(),latched=new Set();return {observe(values,time){const codes=[...new Set(values)];for(const code of latched){if(!codes.includes(code)&&time-(lastSeen.get(code)||0)>=rearmMs)latched.delete(code);}const accepted=[];for(const code of codes){if(!latched.has(code)){accepted.push(code);latched.add(code);}lastSeen.set(code,time);}return accepted;},reset(){lastSeen.clear();latched.clear();}};}
export class ContinuousScanner {
 constructor({onCodes,onStatus,onError}){this.onCodes=onCodes;this.onStatus=onStatus;this.onError=onError;this.running=false;this.controls=null;this.video=null;this.stream=null;this.timer=null;this.generation=0;this.gate=createPresenceGate();}
 async start(video){this.stop();const generation=++this.generation;this.running=true;this.video=video;this.gate.reset();try{
 if(!globalThis.isSecureContext)throw new Error('HTTPS 주소에서 카메라를 사용할 수 있습니다.');if(!navigator.mediaDevices?.getUserMedia)throw new Error('이 브라우저에서 카메라를 지원하지 않습니다. 외부 Chrome/Safari로 열어 주세요.');this.onStatus('카메라 연결 중…');
 const formats=globalThis.BarcodeDetector?await BarcodeDetector.getSupportedFormats():[];if(generation!==this.generation)return;
 if(['code_128','ean_13'].every(f=>formats.includes(f))){const detector=new BarcodeDetector({formats:['code_128','ean_13','qr_code'].filter(f=>formats.includes(f))});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});if(generation!==this.generation){stream.getTracks().forEach(t=>t.stop());return;}this.stream=stream;video.srcObject=stream;await video.play();this.onStatus('카메라 연속 스캔 중');const tick=async()=>{if(!this.running||generation!==this.generation)return;try{const found=await detector.detect(video);this.emit(found.map(x=>x.rawValue));}catch(e){if(e.name!=='InvalidStateError'){this.onError('카메라 인식에 실패했습니다. 다시 시작해 주세요.');this.stop();return;}}if(this.running)this.timer=setTimeout(tick,125);};tick();
 }else{if(!globalThis.ZXingBrowser?.BrowserMultiFormatReader)throw new Error('바코드 인식 모듈을 불러오지 못했습니다. 새로고침해 주세요.');const reader=new ZXingBrowser.BrowserMultiFormatReader(undefined,{delayBetweenScanAttempts:140,delayBetweenScanSuccess:200});const controls=await reader.decodeFromConstraints({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false},video,(result,error,control)=>{if(generation!==this.generation){control?.stop();return;}if(result)this.emit([result.getText()]);else if(error)this.emit([]);});if(generation!==this.generation){controls.stop();return;}this.controls=controls;this.stream=video.srcObject;this.onStatus('카메라 연속 스캔 중');}
 }catch(e){if(generation!==this.generation)return;const message=({NotAllowedError:'카메라 권한이 허용되지 않았습니다. 주소창 권한을 확인하거나 샘플 라벨로 체험하세요.',NotFoundError:'사용할 수 있는 카메라가 없습니다. 샘플 라벨 또는 스캐너 입력을 사용하세요.',NotReadableError:'다른 앱에서 카메라를 사용 중입니다. 종료한 뒤 다시 시작해 주세요.'})[e.name]||e.message;this.stop();this.onError(message);}}
 emit(values){const accepted=this.gate.observe(values,Date.now());if(accepted.length)this.onCodes(accepted);}
 stop(){this.generation++;this.running=false;clearTimeout(this.timer);this.controls?.stop();this.controls=null;this.stream?.getTracks?.().forEach(t=>t.stop());this.stream=null;if(this.video){const stream=this.video.srcObject;stream?.getTracks?.().forEach(t=>t.stop());this.video.srcObject=null;}this.video=null;}
}
